1	/* Pure scenario engine mirrors scripts/predicao_2026/motor.py. */
2	const Prediction2026 = (() => {
3	  "use strict";
4	  const keys = ["lula", "flavio", "outros"];
5	  const defaults = {base:"inclusivo",voto_lula:0,voto_flavio:0,indecisos_validos:1,
6	    indecisos_flavio:null,comparecimento_pp:0,branco_nulo_pp:0,diferencial_pp:0,
7	    vies_pp:0,secoes_abstencao_pp:0,eleitor_provavel:true,exterior:true,
8	    comparecimento_modelo:"uf",regioes:{},ufs:{}};
9	  const sum = a => a.reduce((x,y) => x+y,0);
10	  const clip = (x,lo,hi) => Math.max(lo,Math.min(hi,x));
11	  const norm = a => {const total=sum(a); if(!(total>0)||a.some(x=>!Number.isFinite(x)||x<0))throw Error("Massa inválida");return a.map(x=>x/total);};
12	  function rates(mass,target,diff) {
13	    const offsets=[-diff/2,diff/2,0,0];let lo=-1,hi=1;
14	    for(let i=0;i<50;i++){const mid=(lo+hi)/2;
15	      const total=sum(mass.map((m,k)=>m*clip(target+offsets[k]+mid,0,1)));
16	      if(total<target)lo=mid;else hi=mid;}
17	    return offsets.map(x=>clip(target+x+(lo+hi)/2,0,1));
18	  }
19	  function state(s,params={},vector=null,turnout=null) {
20	    const p={...defaults,...params};
21	    for(const k of ["voto_lula","voto_flavio","indecisos_validos"])
22	      if(!(p[k]>=0&&p[k]<=1))throw Error("Parâmetro fora dos limites: "+k);
23	    const q=(vector||s.bases[p.base]).slice();let pi=norm(q.slice(0,3));
24	    if(p.eleitor_provavel)pi=norm(pi.map((v,k)=>v*s.eleitor_provavel_fatores[k]));
25	    const local=p.ufs[s.uf]||{},useful=[local.voto_lula??p.voto_lula,local.voto_flavio??p.voto_flavio];
26	    if(useful.some(x=>!(x>=0&&x<=1)))throw Error("Voto útil da UF fora dos limites");
27	    const requested=useful.map((x,k)=>x*s.reserva[k]);
28	    const factor=sum(requested)>0?Math.min(1,pi[2]/sum(requested)):1;
29	    const moved=requested.map(v=>v*factor);
30	    pi[0]+=moved[0];pi[1]+=moved[1];pi[2]=Math.max(0,pi[2]-sum(moved));
31	    const undecided=q[3]/Math.max(1e-9,1-q[4]);let destination=pi.slice();
32	    if(p.indecisos_flavio!==null){if(!(p.indecisos_flavio>=0&&p.indecisos_flavio<=1))throw Error("Destino inválido");destination=[1-p.indecisos_flavio,p.indecisos_flavio,0];}
33	    pi=norm(pi.map((v,k)=>(1-undecided)*v+undecided*p.indecisos_validos*destination[k]));
34	    const transfer=clip(p.vies_pp/200,-pi[1],pi[0]);pi[0]-=transfer;pi[1]+=transfer;
35	    const region=p.regioes[s.regiao]||{},uf=p.ufs[s.uf]||{};
36	    const high=sum(s.tse.bins.filter(b=>b.abstencao_historica_pct>=30).map(b=>b.eleitores_2026))/s.eleitorado;
37	    const baseTurnout=p.comparecimento_modelo==="secoes"?s.comparecimento_secoes:s.comparecimento;
38	    const tau=clip((turnout===null?baseTurnout:turnout)+(p.comparecimento_pp+(region.comparecimento_pp||0)+(uf.comparecimento_pp||0)+high*p.secoes_abstencao_pp)/100,0,1);
39	    let invalid=clip(s.branco_nulo+(p.branco_nulo_pp+(uf.branco_nulo_pp||0))/100,0,1);
40	    invalid+=(1-invalid)*undecided*(1-p.indecisos_validos);
41	    const mass=[...pi.map(v=>v*(1-invalid)),invalid];
42	    const differential=(p.diferencial_pp+(uf.diferencial_pp||0))/100;
43	    const r=differential?rates(mass,tau,differential):[tau,tau,tau,tau];
44	    const ballots=mass.map((v,k)=>s.eleitorado*v*r[k]);
45	    const attendance=sum(ballots),valid=sum(ballots.slice(0,3));
46	    return {uf:s.uf,regiao:s.regiao,eleitorado:s.eleitorado,lula:ballots[0],flavio:ballots[1],outros:ballots[2],
47	      branco_nulo:ballots[3],comparecimento:attendance,abstencao:s.eleitorado-attendance,validos:valid,
48	      taxas_por_preferencia:r,demais:Object.fromEntries(["renan_santos","cury","caiado","zema","restantes"].map((k,i)=>[k,ballots[2]*s.outros_composicao[i]]))};
49	  }
50	  function aggregate(rows) {
51	    const fields=["eleitorado","comparecimento","abstencao","branco_nulo",...keys];
52	    const out=Object.fromEntries(fields.map(k=>[k,sum(rows.map(r=>r[k]))]));
53	    out.validos=sum(keys.map(k=>out[k]));
54	    out.percentuais=Object.fromEntries(keys.map(k=>[k,out.validos?100*out[k]/out.validos:0]));
55	    out.margem_flavio_lula=out.percentuais.flavio-out.percentuais.lula;
56	    out.demais=Object.fromEntries(["renan_santos","cury","caiado","zema","restantes"].map(k=>[k,sum(rows.map(r=>r.demais[k]))]));
57	    return out;
58	  }
59	  function scenario(states,params={}) {
60	    const p={...defaults,...params};const rows=states.filter(s=>p.exterior||s.uf!=="ZZ").map(s=>state(s,p));
61	    const regions=Object.fromEntries([...new Set(rows.map(r=>r.regiao))].sort().map(k=>[k,aggregate(rows.filter(r=>r.regiao===k))]));
62	    return {parametros:p,brasil:aggregate(rows),regioes:regions,ufs:rows};
63	  }
64	  function random(seed) {
65	    let x=seed>>>0;return ()=>{x+=0x6D2B79F5;let t=x;t=Math.imul(t^(t>>>15),t|1);t^=t+Math.imul(t^(t>>>7),t|61);return ((t^(t>>>14))>>>0)/4294967296;};
66	  }
67	  function sampler(seed) {
68	    const r=random(seed);let spare=null;
69	    function normal(){if(spare!==null){const v=spare;spare=null;return v;}let u,v,s;
70	      do{u=2*r()-1;v=2*r()-1;s=u*u+v*v;}while(s>=1||s===0);
71	      const f=Math.sqrt(-2*Math.log(s)/s);spare=v*f;return u*f;}
72	    function gamma(a){if(a<1)return gamma(a+1)*Math.pow(Math.max(r(),1e-16),1/a);
73	      const d=a-1/3,c=1/Math.sqrt(9*d);for(;;){const x=normal();let v=1+c*x;if(v<=0)continue;v=v*v*v;const u=r();
74	        if(u<1-.0331*x*x*x*x||Math.log(u)<.5*x*x+d*(1-v+Math.log(v)))return d*v;}}
75	    const dirichlet=a=>norm(a.map(x=>gamma(Math.max(x,1e-6))));
76	    const student=()=>normal()/Math.sqrt(sum(Array.from({length:5},()=>normal()**2))/5);
77	    return {normal,dirichlet,student};
78	  }
79	  function rake(seed,weights,target) {
80	    const q=seed.map(row=>norm(row.map(v=>Math.max(v,1e-9))));
81	    for(let iteration=0;iteration<1000;iteration++) {
82	      const current=target.map((_,k)=>sum(q.map((row,s)=>weights[s]*row[k])));
83	      for(let s=0;s<q.length;s++){for(let k=0;k<target.length;k++)q[s][k]*=current[k]>0?target[k]/current[k]:0;q[s]=norm(q[s]);}
84	      const error=Math.max(...target.map((v,k)=>Math.abs(v-sum(q.map((row,s)=>weights[s]*row[k])))));
85	      if(error<1e-8)return q;
86	    }
87	    throw Error("Calibração não convergiu");
88	  }
89	  const quantile=(a,p)=>{const i=(a.length-1)*p;const lo=Math.floor(i);return a[lo]+(a[Math.ceil(i)]-a[lo])*(i-lo);};
90	  async function simulate(data,params,progress=()=>{},isCancelled=()=>false,runs=2000) {
91	    const p={...defaults,...params},rng=sampler(20261003);
92	    const polls=["pnad","publicado"].includes(p.base)?data.nacional.pareadas:data.nacional.selecionadas;
93	    const kind=["inclusivo","sem_recencia","casas"].includes(p.base)?"previsao_vetor":p.base==="pnad"?"pnad_vetor":"publicado_vetor";
94	    const temporal=norm(polls.map(poll=>p.base==="sem_recencia"?1:poll.peso_recencia));
95	    const domestic=data.estados.filter(s=>s.uf!=="ZZ"),exterior=data.estados.find(s=>s.uf==="ZZ");
96	    const weights=norm(domestic.map(s=>s.eleitorado)),regions=[...new Set(domestic.map(s=>s.regiao))].sort();
97	    const pcts=keys.map(()=>[]),gaps=[];
98	    for(let run=0;run<runs;run++) {
99	      if(isCancelled())return null;
100	      const hw=rng.dirichlet(temporal.map(w=>w*polls.length));
101	      const ps=polls.map(poll=>rng.dirichlet(poll[kind].map(x=>Math.max(x,1e-6)*Math.min(poll.n,2000)/1.5)));
102	      const target=Array.from({length:5},(_,k)=>sum(ps.map((v,h)=>hw[h]*v[k])));
103	      const common=rng.student()*Math.sqrt(3/5)*.01*sum(target.slice(0,3));
104	      const t=clip(common,-target[1],target[0]);target[0]-=t;target[1]+=t;
105	      const seeds=domestic.map(s=>rng.dirichlet(s.bases[p.base].map(x=>Math.max(x,1e-6)*Math.max(s.n_efetivo_assumido,150))));
106	      const q=rake(seeds,weights,target);
107	      const regionVote=regions.map(()=>rng.normal()*.01),regionTurnout=regions.map(()=>rng.normal()*.015);
108	      const commonTurnout=rng.normal()*.01,commonInvalid=rng.normal()*.008;
109	      const rows=domestic.map((s,i)=>{
110	        const ri=regions.indexOf(s.regiao);let pi=norm(q[i].slice(0,3));
111	        if(p.eleitor_provavel)pi=norm(pi.map((v,k)=>v*s.eleitor_provavel_fatores[k]));
112	        const d=clip(regionVote[ri]/2,-pi[1],pi[0]);pi[0]-=d;pi[1]+=d;
113	        const v=[...pi.map(x=>x*sum(q[i].slice(0,3))),...q[i].slice(3)];
114	        const base=p.comparecimento_modelo==="secoes"?s.comparecimento_secoes:s.comparecimento;
115	        const tau=clip(base+commonTurnout+regionTurnout[ri]+rng.normal()*.01,0,1);
116	        return state({...s,branco_nulo:clip(s.branco_nulo+commonInvalid,0,1)},{...p,eleitor_provavel:false},v,tau);
117	      });
118	      if(p.exterior&&exterior){const pi=rng.dirichlet(exterior.bases[p.base].slice(0,3).map(x=>Math.max(x,1e-6)*60));
119	        const v=[...pi.map(x=>x*sum(exterior.bases[p.base].slice(0,3))),...exterior.bases[p.base].slice(3)];
120	        const tau=clip(exterior.comparecimento+rng.normal()*.05,0,1);rows.push(state(exterior,p,v,tau));}
121	      const total=aggregate(rows);keys.forEach((k,i)=>pcts[i].push(total.percentuais[k]));gaps.push(total.margem_flavio_lula);
122	      if((run+1)%100===0){progress(run+1,runs);await new Promise(resolve=>setTimeout(resolve,0));}
123	    }
124	    pcts.forEach(a=>a.sort((a,b)=>a-b));gaps.sort((a,b)=>a-b);
125	    return {runs,intervalos:Object.fromEntries(keys.map((k,i)=>[k,[quantile(pcts[i],.05),quantile(pcts[i],.5),quantile(pcts[i],.95)]])),
126	      margem:[quantile(gaps,.05),quantile(gaps,.95)],p_flavio_a_frente_de_lula:gaps.filter(x=>x>0).length/runs,
127	      p_lula_maioria:pcts[0].filter(x=>x>50).length/runs,p_flavio_maioria:pcts[1].filter(x=>x>50).length/runs};
128	  }
129	  return {defaults,state,aggregate,scenario,rake,simulate};
130	})();
131	if(typeof module!=="undefined"&&module.exports)module.exports=Prediction2026;
