        if p["campo"]["fim"] > today.isoformat():
            continue
        old = selected.get(p["instituto"])
        if old is None or (p["campo"]["fim"], p["divulgacao"], p["id"]) > (
            old["campo"]["fim"],
            old["divulgacao"],
            old["id"],
        ):
            selected[p["instituto"]] = p
    return [selected[k] for k in sorted(selected)]


